insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-12995')::uuid, md5('building-grosse-elbstrasse-43-49-22767')::uuid, '12995', 'grosszuegige-laden-bueroflaeche-mit-traumausblick-direkt-an-der-elbe-12995', 'Großzügige Laden-/ Bürofläche mit Traumausblick direkt an der Elbe', 'Die großzügige, lichtdurchflutete Fläche befindet sich in prominenter Uferlage mit einem herrlichen Blick über die Elbe und den Hamburger Hafen. Sie kann als Laden- oder …', 'Die großzügige, lichtdurchflutete Fläche befindet sich in prominenter Uferlage mit einem herrlichen Blick über die Elbe und den Hamburger Hafen. Sie kann als Laden- oder Bürofläche genutzt werden und bietet für beide Nutzungsarten sehr gute Voraussetzungen. In unmittelbarer Nähe befindet sich die S-Bahnstation Königstraße, die Buslinie 111 sowie die Hadag-Fähre. Das direkte Umfeld ist geprägt von renommierten Nachbarn wie dem Stilwerk und zahlreichen namenhaften Gastronomen. Fläche erschließt sich über einen repräsentativen Eingangsbereich, unterteilt sich in diverse, optisch getrennte Ebenen und verfügt über einen Abstellraum sowie große bodentiefe Fenster mit optimaler Sichtbarkeit und Außendarstellung, zur möglichen Nutzung als Ladenfläche. Sonst wurde diese Fläche auch bereits als Büro genutzt und kann dem entsprechen umfunktioniert werden und verfügt schon über eine CAT-7 Verkabelung.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['erdgeschoss', 'wasserblick']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_12995.pdf', null, 'filemaker', '12995') on conflict (id) do nothing;
