insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25443')::uuid, md5('building-vorsetzen-32-39-20459')::uuid, '25443', 'boa-vista-hochwertige-bueroflaeche-im-portugiesenviertel-an-der-elbe-25443', 'Boa Vista: Hochwertige Bürofläche im Portugiesenviertel an der Elbe', 'Das markante Bürogebäude befindet sich in bester Citylage direkt an der Elbe. Die U-Bahnstation Baumwall liegt nur wenige Fußminuten entfernt und sichert eine sehr gute Anbindung …', 'Das markante Bürogebäude befindet sich in bester Citylage direkt an der Elbe. Die U-Bahnstation Baumwall liegt nur wenige Fußminuten entfernt und sichert eine sehr gute Anbindung an das öffentliche Verkehrsnetz. Zahlreiche kleine Geschäfte und eine großes Angebot an Cafés und Restaurants im angrenzenden Portugiesenviertel unterstreichen die Attraktivität dieser lebendigen Lage. Die helle Bürofläche erschließt sich über ein modernes Foyer mit zwei Personenaufzügen. Die hochwertige Ausstattung umfasst Teppich- und Designfußboden, bodentiefe Fenster, Beleuchtungssysteme, Bodentanks, eine Kühlung über Betonkernaktivierung, Akustikelemente im Deckenbereich, außenliegenden, elektrischen Sonnenschutz, teilweise Glastrennwände, 3 Meter Deckenhöhe, separate WC-Einheiten und eine moderne Pantry. PKW- Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 204, 647, 'https://www.buerohamburg.de/objects/pdf/BHI_25443.pdf', null, 'filemaker', '25443') on conflict (id) do nothing;
