insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-20386')::uuid, md5('building-wendenstrasse-408-20537')::uuid, '20386', 'hamm-flexibel-gestaltbare-bueroflaeche-20386', 'Hamm: Flexibel gestaltbare Bürofläche', 'Das markante Bürogebäude befindet sich in ruhiger City-Süd-Lage zwischen Süderstraße und Eiffestraße, unweit der Elbbrücken und der U-Bahnstation Burgstraße. Das Gebäude verfügt …', 'Das markante Bürogebäude befindet sich in ruhiger City-Süd-Lage zwischen Süderstraße und Eiffestraße, unweit der Elbbrücken und der U-Bahnstation Burgstraße. Das Gebäude verfügt über einen erst kürzlich renovierten Eingangsbereich, einen Personenaufzug sowie einen Lastenaufzug, welcher seitlich des Gebäudes liegt. Zur derzeitigen Ausstattung zählen Teppichfußboden, Kabelkanäle, eine Teeküche sowie getrennte WC-Einheiten. Die vakante Fläche kann nach Rücksprache mit dem Vermieter individuell aufgeteilt und ausgebaut werden. Der Mietpreis variiert je nach Ausstattungswunsch ab Euro 9,75 pro qm. PKW-Stellplätze können nach Rücksprache auf dem Gelände angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['lastenaufzug', 'stellplaetze']::text[], 292, 943, 'https://www.buerohamburg.de/objects/pdf/BHI_20386.pdf', null, 'filemaker', '20386') on conflict (id) do nothing;
