insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-12464')::uuid, md5('building-essener-strasse-4-22419')::uuid, '12464', 'ruhige-bueroflaeche-mit-blick-ins-gruene-12464', 'Ruhige Bürofläche mit Blick ins Grüne', 'Das ehemalige Fabrikgebäude befindet sich in ruhiger Lage auf einem vielseitigen Gewerbehof im Norden Hamburgs. Über die nahe gelegene Langenhorner Chaussee ist die Hamburger …', 'Das ehemalige Fabrikgebäude befindet sich in ruhiger Lage auf einem vielseitigen Gewerbehof im Norden Hamburgs. Über die nahe gelegene Langenhorner Chaussee ist die Hamburger Innenstadt in ca. 15 Minuten erreicht. Auch der Flughafen, die A7-Anschlussstelle Schnelsen-Nord sowie die U-Bahnstation Langenhorn Nord liegen nur ca. 5 Autominuten entfernt. Über ein großzügges Treppenhaus erreicht man die im 2. Obgerschoss gelegene Bürofläche. Zur aktuellen Ausstattung zählen teilweise Designboden, Konferenzraum mit Klimaanlage Fensterbrüstungskanäle, eine Pantry sowie getrennte WC-Einheiten. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], 229, 1705, 'https://www.buerohamburg.de/objects/pdf/BHI_12464.pdf', null, 'filemaker', '12464') on conflict (id) do nothing;
