insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-20969')::uuid, md5('building-willy-brandt-strasse-59-20457')::uuid, '20969', 'modernes-bueroquartier-am-nikloaifleet-20969', 'Modernes Büroquartier am Nikloaifleet', 'Das denkmalgeschützte Objekt befindet sich in verkehrsgünstiger Lage des südlichen Innenstadtkerns zwischen Willy-Brandt-Straße und Nikolaifleet. Es wurde 2016 aufwendig …', 'Das denkmalgeschützte Objekt befindet sich in verkehrsgünstiger Lage des südlichen Innenstadtkerns zwischen Willy-Brandt-Straße und Nikolaifleet. Es wurde 2016 aufwendig kernsaniert. Diverse U- und S- Bahnstationen sind fußläufig schnell erreicht und sichern eine gute Anbindung an das öffentliche Verkehrsnetz. Das direkte Umfeld ist durch zahlreiche Einkaufsmöglichkeiten, Cafés und Restaurants geprägt. Die Mietflächen sind bereits sehr hochwertig ausgebaut und können an die individuellen Aufteilungs- und Ausstattungswünsche des zukünftigen Mieters angepasst werden. Die Grundausstattung umfasst unter anderem bodentiefe Fenster sowie Akustik- und Kühldecken. Der Mietpreis richtet sich nach den individuellen Umbauwünschen des neuen Mieters.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-20969-1')::uuid, md5('property-20969')::uuid, 'Mietfläche', 674, 25.5, null, 'filemaker', '20969-1') on conflict (id) do nothing;
