insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22591')::uuid, md5('building-borsteler-chaussee-43-55-22453')::uuid, '22591', 'vielseitige-nutzungsmoeglichkeiten-im-alpha-park-22591', 'Vielseitige Nutzungsmöglichkeiten im Alpha Park', 'Der Gewerbehof Alpha Park befindet sich in verkehrsgünstiger Lage zwischen Eppendorf und dem Hamburger Flughafen. Diverse Buslinien erschließen das Areal. In der näheren Umgebung …', 'Der Gewerbehof Alpha Park befindet sich in verkehrsgünstiger Lage zwischen Eppendorf und dem Hamburger Flughafen. Diverse Buslinien erschließen das Areal. In der näheren Umgebung befinden sich Restaurants und Cafés sowie Geschäfte des täglichen Bedarfs. Die gut belichtete Bürofläche ist u.a. mit einem Teppichboden, einer abgehängten Decke mit integrierter Beleuchtung, einem umlaufenden Fensterbrüstungskanal sowie einer Teeküche ausgestattet. Die Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter, sodass der oben genante Mietpreis variieren kann. Pkw-Stellplätze können sowohl auf dem Hof als auch in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], 98, 870, 'https://www.buerohamburg.de/objects/pdf/BHI_22591.pdf', null, 'filemaker', '22591') on conflict (id) do nothing;
