insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-20522')::uuid, md5('building-spitalerstrasse-32-20095')::uuid, '20522', 'innenstadt-grosszuegiges-buero-in-sehr-guter-lauflage-20522', 'Innenstadt: Großzügiges Büro in sehr guter Lauflage', 'Das gepflegte Geschäftsgebäude in lebendiger Innenstadtlage mit unmittelbarer Nähe zum Hauptbahnhof gewährleistet einen zentralen Bürostandort. Der Anschluss an den ÖPNV ist durch …', 'Das gepflegte Geschäftsgebäude in lebendiger Innenstadtlage mit unmittelbarer Nähe zum Hauptbahnhof gewährleistet einen zentralen Bürostandort. Der Anschluss an den ÖPNV ist durch diverse Buslinien und alle Nah- und Fernverbindungen gesichert. Sowohl die Spitalerstraße als auch die sich im direkten Umfeld befindende Mönckebergstraße zählen zu den belebtesten Einkaufsstraßen Hamburgs. Ein vielseitiges, gastronomisches Angebot sorgt für abwechslungsreiche Mittagspausen. Die Ausstattung der Bürofläche umfasst unter anderem Teppichfußboden, separate WC-Einheiten, eine Teeküche sowie eine abgehängte Decke mit EDV-gerechter Beleuchtung. Die weitere Gestaltung der Bürofläche erfolgt in Absprache mit dem zukünftigen Mieter. Die Innenansichten stammen aus einer ähnlichen Fläche im Gebäude. Pkw-Stellplätze können im Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['lastenaufzug']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_20522.pdf', null, 'filemaker', '20522') on conflict (id) do nothing;
