insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24248')::uuid, md5('building-frankenstrasse-3-7-20097')::uuid, '24248', 'moderne-bueroflaeche-in-verkehrsguenstiger-lage-24248', 'Moderne Bürofläche in verkehrsgünstiger Lage', 'Das Bürogebäude befindet sich in einer ruhigen und verkehrsgünstigen Lage, unweit der S-Bahnstation Hammerbrook. Eine schnelle Anbindung an die City sowie die …', 'Das Bürogebäude befindet sich in einer ruhigen und verkehrsgünstigen Lage, unweit der S-Bahnstation Hammerbrook. Eine schnelle Anbindung an die City sowie die Autobahnanschlussstelle ist gegeben. Eine vielseitige Auswahl gastronomischer Betriebe sowie Geschäfte für kleinere Einkäufe sind fußläufig schnell erreicht. Die vakante Bürofläche wird über ein Foyer mit Personenaufzug erschlossen. Die zukünftige Raumaufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. Die hier ausgewählten Bilder stammen aus einer bereits ausgebauten Flächen im Gebäude und sind beispielhaft gewählt. PKW-Stellplätze können nach Rücksprache angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 150, 680, 'https://www.buerohamburg.de/objects/pdf/BHI_24248.pdf', null, 'filemaker', '24248') on conflict (id) do nothing;
