insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-7158')::uuid, md5('building-ueberseering-21-25-22297')::uuid, '7158', 'flexible-bueroflaechen-in-verkehrsguenstiger-lage-7158', 'Flexible Büroflächen in verkehrsgünstiger Lage', 'Die City-Nord gehört zu den bekanntesten und wichtigsten Bürostandorten Hamburgs. Nicht nur die sehr gute Anbindung an den öffentlichen Nahverkehr und den Flughafen, sondern auch …', 'Die City-Nord gehört zu den bekanntesten und wichtigsten Bürostandorten Hamburgs. Nicht nur die sehr gute Anbindung an den öffentlichen Nahverkehr und den Flughafen, sondern auch die unmittelbare Nähe zum Stadtpark machen diese Lage so attraktiv. Die helle Bürofläche wird über einen Personenaufzug erschlossen und befindet sich derzeit im Rohbau. Die Ausbau- und Ausstattungswünsche erfolgen in Rücksprache mit dem zukünftigen Mieter. Der Mietpreis richtet sich dementsprechend. Die Innenansichten sind beispielhaft gewählt. PKW-Stellplätze können vor Ort angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 114, 937, 'https://www.buerohamburg.de/objects/pdf/BHI_7158.pdf', null, 'filemaker', '7158') on conflict (id) do nothing;
