insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-20977')::uuid, md5('building-willy-brandt-strasse-59-20457')::uuid, '20977', 'untervermietung-modernes-bueroquartier-am-nikloaifleet-20977', 'Untervermietung: Modernes Büroquartier am Nikloaifleet', 'Das denkmalgeschützte Objekt befindet sich in verkehrsgünstiger Lage des südlichen Innenstadtkerns zwischen Willy-Brandt-Straße und Nikolaifleet. Es wurde 2016 aufwendig …', 'Das denkmalgeschützte Objekt befindet sich in verkehrsgünstiger Lage des südlichen Innenstadtkerns zwischen Willy-Brandt-Straße und Nikolaifleet. Es wurde 2016 aufwendig kernsaniert. Diverse U- und S- Bahnstationen sind fußläufig schnell erreicht und sichern eine gute Anbindung an das öffentliche Verkehrsnetz. Das direkte Umfeld ist durch zahlreiche Einkaufsmöglichkeiten, Cafés und Restaurants geprägt. Die Mietflächen sind bereits sehr hochwertig ausgebaut. Die Grundausstattung umfasst unter anderem bodentiefe Fenster, CAT.7 -Verkabelung, außenliegender Sonnenschutz, eine Pantry, Zutrittskontrollsystem sowie Akustik- und Kühldecken. Die Bilder sind beispielhaft gewählt und stammen aus einer ähnlichen Flächen im Objekt. Der Mietpreis variiert je nach Lage und Ausstattung im Objekt. PKW- Stellplätze können in der hauseigenen Tiefgarage angemietet werden. Bei dieser Mietfläche handelt es sich um ein Untermietverhältnis.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'stellplaetze', 'wasserblick']::text[], 632, 4122, 'https://www.buerohamburg.de/objects/pdf/BHI_20977.pdf', null, 'filemaker', '20977') on conflict (id) do nothing;
