insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25024')::uuid, md5('building-nagelsweg-33-35-20097')::uuid, '25024', 'cambium-moderne-bueroflaeche-in-zentraler-city-sued-lage-25024', 'Cambium: Moderne Bürofläche in zentraler City-Süd-Lage', 'Das funktionale Bürogebäude Cambium befindet sich im Herzen der City-Süd, angrenzend an den ruhigen Mittelkanal. Die S-Bahnstation Hammerbrook ist fußläufig in wenigen Minuten …', 'Das funktionale Bürogebäude Cambium befindet sich im Herzen der City-Süd, angrenzend an den ruhigen Mittelkanal. Die S-Bahnstation Hammerbrook ist fußläufig in wenigen Minuten erreicht und sichert eine gute Anbindung an die Hamburger Innenstadt und den Hauptbahnhof. Die helle Bürofläche wird über ein großzügiges Foyer erschlossen und kann in Absprache mit dem zukünftigen Mieter neu aufgeteilt werden. Die derzeitige Ausstattung umfasst bodentiefe, teilweise Glastrennwände,Teppichbodenbelag, Beleuchtungssysteme, innen liegenden und teilweise außen liegenden Sonnenschutz, separate WC-Einheiten und eine Pantry. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_25024.pdf', null, 'filemaker', '25024') on conflict (id) do nothing;
