insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-12658')::uuid, md5('building-breite-strasse-61-22767')::uuid, '12658', 'hochwertig-ausgebaute-mietflaeche-zwischen-fischmarkt-und-altona-12658', 'Hochwertig ausgebaute Mietfläche zwischen Fischmarkt und Altona', 'Der markante Bürokomplex befindet sich verkehrsgünstig in bester Nachbarschaft zur Großen Elbstraße. Die nahe gelegene S-Bahn-Station Königstraße und diverse Buslinien sichern …', 'Der markante Bürokomplex befindet sich verkehrsgünstig in bester Nachbarschaft zur Großen Elbstraße. Die nahe gelegene S-Bahn-Station Königstraße und diverse Buslinien sichern eine sehr gute ÖPNV-Anbindung. Vielseitige Einkaufsmöglichkeiten und diverse Cafés und Restaurants beleben das direkte Umfeld. Die moderne Bürofläche ist barrierefrei und erschließt sich über zwei Personenaufzüge. Die aktuelle Ausstattung umfasst unter anderem Teppichbodenbelag, teilweise Glastrennwände, eine Akustikdecke mit integrierter Beleuchtung, ein klimatisierter Serverraum, eine EDV-Verkabelung, eine großzügige Pantry und mehrere separate Sanitäreinheiten. Darüber hinaus steht dem Mieter ein kleiner Balkon zur exklusiven Nutzung zu Verfügung. PKW-Stellplätze und ein Lagerraum können bei Bedarf in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'barrierefrei', 'wasserblick']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_12658.pdf', null, 'filemaker', '12658') on conflict (id) do nothing;
