insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-18592')::uuid, md5('building-ludwig-erhard-strasse-14-20459')::uuid, '18592', 'bueroflaeche-in-zentraler-lage-zwischen-michel-und-fleetinsel-18592', 'Bürofläche in zentraler Lage zwischen Michel und Fleetinsel', 'Das markante und repräsentative Büro- und Geschäftshaus besticht durch seine hervorragende Lage in der Hamburger Innenstadt – zwischen dem Michel und der Fleetinsel. Der …', 'Das markante und repräsentative Büro- und Geschäftshaus besticht durch seine hervorragende Lage in der Hamburger Innenstadt – zwischen dem Michel und der Fleetinsel. Der Großneumarkt mit vielfältigen Einkaufsmöglichkeiten des täglichen Bedarfs sowie zahlreichen Cafés und Restaurants ist fußläufig erreichbar. Die S-Bahn-Station Stadthausbrücke befindet sich nur wenige Meter entfernt und sorgt für eine optimale Anbindung an den öffentlichen Nahverkehr. Das moderne 7-geschossige Bürogebäude verfügt über ein lichtdurchflutetes Treppenhaus an der Stirnseite und wird über zwei Glasaufzüge erschlossen. Das repräsentative Foyer mit verglastem Treppenhaus schafft eine einladende Atmosphäre. Die Bürofläche ist hochwertig ausgestattet mit Teppichfußboden, modernen Beleuchtungssystemen, außenliegendem elektrischen Sonnenschutz sowie einer CAT-6-Verkabelung in Fußbodenkabelkanälen. Zudem stehen getrennte WC-Bereiche und eine Teeküche zur Verfügung. PKW-Stellplätze können in umliegenden Parkhäusern angemietet werden. Die Bürofläche wird im Rahmen eines Untermietverhältnisses bis zum 31.08.2030 angeboten und ist sofort bezugsfertig.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei']::text[], 397, 704, 'https://www.buerohamburg.de/objects/pdf/BHI_18592.pdf', null, 'filemaker', '18592') on conflict (id) do nothing;
