insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25118')::uuid, md5('building-raboisen-6-20095')::uuid, '25118', 'moderne-bueroflaeche-in-zentraler-citylage-mit-zwei-terrassen-und-alsterblick-25118', 'Moderne Bürofläche in zentraler Citylage mit zwei Terrassen und Alsterblick', 'Der DGNB zertifizierte Neubau befindet sich in zentraler Innenstadtlage unmittelbar zwischen dem Hauptbahnhof und der Binnenalster. Das Umfeld ist geprägt durch alle Geschäfte des …', 'Der DGNB zertifizierte Neubau befindet sich in zentraler Innenstadtlage unmittelbar zwischen dem Hauptbahnhof und der Binnenalster. Das Umfeld ist geprägt durch alle Geschäfte des täglichen Bedarfs sowie zahlreiche Cafés und Restaurants. Der nur wenige Meter entfernte Hauptbahnhof sorgt für eine optimale Anbindung an das öffentliche Verkehrsnetz. Über ein großzügiges zweigeschossiges Foyer mit zwei Personen erreicht man die helle Bürofläche. Zur Ausstattung zählen Teppich- und Amticofußboden, Beleuchtungssystme, bodentiefe Fenster, außen liegender elektrischer Sonnenschutz, Bodentanks, zwei WC-Kerne mit jeweils Damen- und Herren-WC sowie eine modernen Pantry. Highlight ist zwei große Terrassen. PKW-Stellplätze können im Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse']::text[], 235, 710, 'https://www.buerohamburg.de/objects/pdf/BHI_25118.pdf', null, 'filemaker', '25118') on conflict (id) do nothing;
